      "evidence": [
        {"kind": "metric", "sql": "SELECT max(value) AS restarts_abnormal FROM abnormal_metrics WHERE attr_k8s_pod_name='ts-order-service-6f4cfb5df7-27ppv' AND metric='k8s.container.restarts'", "claim": "Order-service pod restart counter rises from 0 in normal to 1 in the abnormal window."},
        {"kind": "trace", "sql": "SELECT (SELECT count(*) FROM normal_traces WHERE service_name='ts-order-service') AS normal_spans, (SELECT count(*) FROM abnormal_traces WHERE service_name='ts-order-service') AS abnormal_spans", "claim": "Order-service emits about 1,549 spans/min normally but only about 10 spans in the whole abnormal window, then goes silent."},
        {"kind": "metric", "sql": "SELECT avg(value) AS abn_cpu, (SELECT avg(value) FROM normal_metrics WHERE service_name='ts-order-service' AND metric='container.cpu.usage') AS norm_cpu FROM abnormal_metrics WHERE service_name='ts-order-service' AND metric='container.cpu.usage'", "claim": "Order-service container CPU collapses to near zero during the incident, consistent with the pod not serving requests."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-order-service", "to": "ts-seat-service", "evidence": [{"kind": "trace", "sql": "SELECT count(*) AS n, avg(duration)/1e6 AS avg_ms FROM abnormal_traces WHERE service_name='ts-seat-service' AND attr_span_kind='Client' AND attr_http_response_status_code=503", "claim": "Seat-service client calls to order-service return 503 after about 3.5 s in the abnormal window; normal averages about 7 ms."}]},
    {"from": "ts-seat-service", "to": "ts-travel-service", "evidence": [{"kind": "trace", "sql": "SELECT count(*) AS calls, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errs FROM abnormal_traces WHERE service_name='ts-seat-service' AND span_name LIKE '%getLeftTicketOfInterval%'", "claim": "31 of 47 seat left-ticket requests fail with errors, averaging about 2.3 s, and travel-service calls to seat fail with 500s."}]},
    {"from": "ts-travel-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_http_response_status_code AS code, count(*) AS n FROM abnormal_traces WHERE service_name IN ('ts-travel-service','ts-route-plan-service') AND attr_http_response_status_code >= 500 GROUP BY ALL", "claim": "Travel-service 500s and route-plan 504s appear together in the abnormal window, with route-plan calls to travel taking around 60 s."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_http_response_status_code AS code, count(*) AS n FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_http_response_status_code >= 500 GROUP BY ALL", "claim": "Travel-plan-service returns 500/504 on minStation and minStopStations plans, reflecting timeouts from route-plan."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "log", "sql": "SELECT count(*) AS n FROM abnormal_logs WHERE service_name='ts-ui-dashboard' AND level='ERROR'", "claim": "Ui-dashboard logs errors on handled requests, including 503s upstream of the travel-plan timeouts."}]}
  ]
}
